-- Reviewed roster aliases for source spellings that differ from the guide.
INSERT OR IGNORE INTO election_candidate_aliases (source_id, raw_name_normalized, candidate_id, confidence)
SELECT src.id, 'KENNETH R. CASNER', c.id, 'confirmed_official_roster'
FROM election_sources src, candidates c
WHERE src.source_key LIKE 'wy|%|wy-2026-primary|sos_candidates_summary'
  AND c.full_name = 'Kenneth R Casner';

